import { matchPath } from './match-path.js';
import { fail } from './respond.js';
import { catalogRoutes } from './routes/catalog.js';
import { holdRoutes } from './routes/holds.js';
import { loanRoutes } from './routes/loans.js';
import { memberRoutes } from './routes/members.js';

/**
 * Builds the lending desk API over a store. Its handle(request) takes { method, path, query,
 * body, today } and returns { status, body }.
 */
export function createApp(store) {
  const routes = [
    ...loanRoutes(store),
    ...holdRoutes(store),
    ...memberRoutes(store),
    ...catalogRoutes(store),
  ];
  return {
    handle(request) {
      for (const route of routes) {
        if (route.method !== request.method) continue;
        const params = matchPath(route.path, request.path);
        if (params !== null) return route.handle({ ...request, params });
      }
      return fail(404, 'route-not-found', `No route for ${request.method} ${request.path}`);
    },
  };
}
import { outstandingBalance } from '../../fees/balance.js';
import { formatCents } from '../../helpers/money.js';
import { displayName } from '../../members/accounts.js';
import { listOverdueLoans } from '../../reports/overdue.js';
import { ok } from '../respond.js';

/** The routes about a member's account. */
export function memberRoutes(store) {
  return [
    {
      method: 'GET',
      path: '/members/:id/summary',
      handle: ({ params, today }) => {
        const member = store.getMember(params.id);
        const balanceCents = outstandingBalance(store, member.id);
        return ok({
          id: member.id,
          name: displayName(member),
          loanCount: store.listOpenLoans(member.id).length,
          overdueCount: listOverdueLoans(store, today).filter((loan) => loan.memberId === member.id).length,
          balanceCents,
          balance: formatCents(balanceCents),
        });
      },
    },
  ];
}
/** A successful response with a JSON body. */
export function ok(body, status = 200) {
  return { status, body };
}

/** A failed response: { error: { code, message } }, the format every route answers errors in. */
export function fail(status, code, message) {
  return { status, body: { error: { code, message } } };
}
